/**
 * 根據版本模式 ('v2' | 'v1') 回傳整合後的 17 職業完整技能樹資料
 */
function getMergedProfessionsData(versionMode) {
  const cloned = JSON.parse(JSON.stringify(allProfessionsData));

  const GRADE_TO_STAGE_INDEX = {
    '1轉': 1,
    '一轉': 1,
    '二轉': 2,
    '三轉': 3,
    '四轉': 4
  };

  // 新增技能預設前置與插入設定
  const NEW_SKILL_CONFIG = {
    blessArmor: { preRequisite: {} },
    shieldPower: { preRequisite: {} },
    paladinGuard: { preRequisite: {} },
    darkImpale: { preRequisite: { darkSoul: 10 } },
    poisonMastery1: { preRequisite: {} },
    poisonMastery2: { preRequisite: { poisonMastery1: 20 } },
    poisonMastery3: { preRequisite: { poisonMastery2: 20 } },
    freezeEffect: { preRequisite: {} },
    shatterFreeze: { preRequisite: { freezeEffect: 30 } },
    holyAura: { preRequisite: { holySymbol: 30 } },
    superHolySymbol: { preRequisite: { holyAura: 10 } },
    assassinateFinish: { preRequisite: { assassinate: 20 } }
  };

  for (const meta of PROFESSION_META) {
    const profData = cloned[meta.profKey];
    const patchProf = balancePatchV2Data[meta.slug];
    if (!profData || !patchProf) continue;

    // 建置快速查詢表
    const patchByMappedId = new Map();
    for (const ps of patchProf.skills) {
      patchByMappedId.set(ps.mappedSkillId, ps);
    }

    // 先為所有既有技能掛載 V2 資訊
    for (const stageKey of profData.jobStagesOrder) {
      const stageSkills = profData.skills[stageKey] || [];
      for (const s of stageSkills) {
        const ps = patchByMappedId.get(s.id);
        if (!ps) continue;

        s.v2Patch = ps;
        if (meta.faction === 'cygnus') {
          s.v2Status = 'cygnus';
        } else if (ps.tags.includes('刪除')) {
          s.v2Status = 'deleted';
        } else if (ps.oldName || ps.mappedSkillId === 'blind') {
          s.v2Status = 'reworked';
        } else {
          s.v2Status = 'modified';
        }

        if (versionMode === 'v2') {
          if (ps.oldName) {
            s.v1Name = s.name;
            s.name = ps.name;
          } else if (ps.name && ps.name !== s.name) {
            s.v1Name = s.name;
            s.name = ps.name;
          }
          if (ps.icon) s.imageUrl = ps.icon;
          if (ps.maxLevel && ps.maxLevel > 0) s.maxLevel = ps.maxLevel;
          if (ps.desc) {
            s.description = ps.desc.replace(/\n/g, '<br>');
          }
          if (meta.slug === 'marksman' && s.id === 'blind') {
            s.preRequisite = { snipe: 10 };
          }
          // 依據 V2 各等級數值更新 levels 描述
          if (ps.panels && ps.panels.length > 0) {
            const p0 = ps.panels[0];
            if (!Array.isArray(s.levels)) s.levels = [null];
            for (let lv = 1; lv <= s.maxLevel; lv++) {
              const idx = lv - (p0.from || 1);
              const parts = [];
              for (const panel of ps.panels) {
                for (const st of panel.stats) {
                  const val = st.afterText[idx];
                  if (val && val !== '無') {
                    parts.push(st.label + ': ' + val);
                  }
                }
              }
              if (parts.length > 0) {
                s.levels[lv] = {
                  effect: parts.join('、'),
                  fullDescription: 'Lv.' + lv + ': ' + parts.join('、')
                };
              }
            }
          }
        }
      }
    }

    // 在 V2 模式下插入全新新增的技能 (冒險家V2新增；皇家騎士團已包含在基礎技能樹)
    if (versionMode === 'v2' && meta.faction !== 'cygnus') {
      for (const ps of patchProf.skills) {
        if (!ps.tags.includes('新增')) continue;
        const alreadyExists = profData.jobStagesOrder.some(st =>
          (profData.skills[st] || []).some(s => s.id === ps.mappedSkillId)
        );
        if (alreadyExists) continue;

        const stageIdx = GRADE_TO_STAGE_INDEX[ps.grade] || 4;
        const targetStageKey = profData.jobStagesOrder[stageIdx];
        if (!targetStageKey || !profData.skills[targetStageKey]) continue;

        const maxLv = ps.maxLevel || 20;
        const levels = [null];
        for (let lv = 1; lv <= maxLv; lv++) {
          const parts = [];
          for (const panel of (ps.panels || [])) {
            const idx = lv - (panel.from || 1);
            for (const st of panel.stats) {
              const val = st.afterText[idx];
              if (val && val !== '無') {
                parts.push(st.label + ': ' + val);
              }
            }
          }
          const effectText = parts.length > 0 ? parts.join('、') : (ps.changes && ps.changes.length ? ps.changes.map(c => c.label + ': ' + c.after).join('、') : 'V2 新增技能');
          levels.push({
            effect: effectText,
            fullDescription: 'Lv.' + lv + ': ' + effectText
          });
        }

        const cfg = NEW_SKILL_CONFIG[ps.mappedSkillId] || { preRequisite: {} };
        const reqLevelByStage = { 1: 10, 2: 30, 3: 70, 4: 120 };

        profData.skills[targetStageKey].push({
          id: ps.mappedSkillId,
          name: ps.name,
          maxLevel: maxLv,
          requiredLevel: reqLevelByStage[stageIdx] || 120,
          preRequisite: cfg.preRequisite,
          description: (ps.desc || '').replace(/\n/g, '<br>'),
          imageUrl: ps.icon || '',
          levels,
          v2Status: 'new',
          v2Patch: ps
        });
      }
    }
  }

  return cloned;
}
